import{_ as t,c as o,o as a,ae as r}from"./chunks/framework.Bi6zybwU.js";const h=JSON.parse('{"title":"WooCommerce Integration","description":"WooCommerce Integration","frontmatter":{"title":"WooCommerce Integration","description":"WooCommerce Integration"},"headers":[],"relativePath":"guide/data-sources/woocommerce-integration.md","filePath":"guide/data-sources/woocommerce-integration.md"}'),n={name:"guide/data-sources/woocommerce-integration.md"};function i(s,e,c,l,m,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="woocommerce-integration" tabindex="-1">WooCommerce Integration <a class="header-anchor" href="#woocommerce-integration" aria-label="Permalink to &quot;WooCommerce Integration&quot;">​</a></h1><p>Making a table with **WooCommerce Products **is a versatile feature of Ninja Tables. WooCommerce integration with Ninja Tables lets you create and customize smart product tables easily. WooCommerce Integration is a Pro Feature.</p><h2 id="create-woocommerce-tables" tabindex="-1">Create WooCommerce Tables <a class="header-anchor" href="#create-woocommerce-tables" aria-label="Permalink to &quot;Create WooCommerce Tables&quot;">​</a></h2><ul><li>Click on <strong>Add Table</strong> from the upper right corner to create a new table.</li><li>Go to the <strong>WooCommerce</strong> <strong>Table</strong> from the left sidebar. <img src="https://ninjatables.com/wp-content/uploads/2022/10/WooCommerce-Table-1-scaled.webp" alt="WooCommerce Table"></li><li>Add the <strong>table name</strong> &amp; then filter the <strong>products</strong>. Choose the **product categories **&amp; <strong>tags</strong> you wish to include in the table.</li><li>From product type, filter your desired products from simple, variable, and grouped products options.</li><li>In this case, suppose you have selected the clothing category from the categories tab and simply from the product type tags. All of the single clothing products will be displayed in the table.</li><li>And when you wish to hide the products that are out of stock, then check the <strong>Hide out-of-stock items</strong>.</li><li>Select the **Initial Order by options **to order all the products by the date, product title, price, etc.</li><li>Then click the **Create product table **button. The table would look like the following screenshot. All settings can be changed after creating the table and you can customize the product table using Ninja Tables features.</li><li>You can choose from the <strong>Appearance</strong> tab where you want to view the details of the cart. <img src="https://ninjatables.com/wp-content/uploads/2022/10/WooCommerce-Table-2-scaled.webp" alt=""></li><li>Here, the option to display the <strong>cart</strong> and <strong>checkout</strong> icon both before and after the table is** **selected.</li><li>Along with cart info, you can also pick cart &amp; checkout icons.</li><li>There is also a selection for Variable Products. You can see a dropdown where consumers can select variable options for their product; there may also be price differences depending on the variable options that users have selected.</li><li>The tab for the **Query Settings <strong>is basically the same settings you made during the</strong> **table setting. See the image below. You may then adjust your initial settings from this tab. <img src="https://ninjatables.com/wp-content/uploads/2022/10/WooCommerce-Table-3-scaled.webp" alt=""></li><li>You can make a custom column from the <strong>Add New Column</strong> tab to your table of products.</li><li>Set a name for the column, select the type of data, and choose the field type. In this case, the product column is called SKU to show the product SKU. <img src="https://ninjatables.com/wp-content/uploads/2022/10/WooCommerce-Table-Dynamic-Field--scaled.webp" alt=""></li><li>Lastly, click on the <strong>Add Column</strong> button to create the column, and your custom column will look like this. <img src="https://ninjatables.com/wp-content/uploads/2023/02/Woocommerce-Integration-10.png" alt="product sku column in woocommerce table"> The remainder of the <a href="https://ninjatables.com/docs-category/column-settings/" target="_blank" rel="noreferrer">column settings</a> are like every other Ninja Tables column.</li></ul><h3 id="customize-a-woocommerce-table-using-ninja-tables" tabindex="-1">Customize a WooCommerce Table Using Ninja Tables <a class="header-anchor" href="#customize-a-woocommerce-table-using-ninja-tables" aria-label="Permalink to &quot;Customize a WooCommerce Table Using Ninja Tables&quot;">​</a></h3><p>Ninja Tables has a huge set of features to help you customize and control any table you create with this plugin. And for WooCommerce, the customization options are even better! Here&#39;s a fully customized WooCommerce product table demo. [ninja_tables id=&quot;3792&quot;] This table used custom colors, design, product variations, search bar, pagination, and custom coding. You can customize WooCommerce tables further using custom CSS or Ninja Tables coloring and designing options.</p>',6)])])}const g=t(n,[["render",i]]);export{h as __pageData,g as default};
